const p=Math.min(32,v.p+tileDepth),count=2**(p-v.p);$('tilePrefix').replaceChildren(...Array.from({length:Math.min(8,32-v.p)+1},(_,i)=>{const op=element('option','/'+(v.p+i)+' · '+fmt(2**i)+' blocks');op.value=v.p+i;op.selected=v.p+i===p;return op}));$('tilePrefix').onchange=()=>{tileDepth=Number($('tilePrefix').value)-v.p;drawZoom()};$('tileInfo').textContent=fmt(count)+' equal blocks · '+fmt(N.size(p))+' IPs each';$('zoomGrid').className='zoomgrid'+(count>64?' dense':count>16?' medium':'');$('zoomGrid').style.setProperty('--columns',Math.min(8,Math.max(1,Math.ceil(Math.sqrt(count)))));const reservations=plan.allocations.map(a=>({...N.parse(a.cidr),record:a}));$('zoomGrid').replaceChildren(...Array.from({length:count},(_,i)=>{const start=v.start+i*N.size(p),end=start+N.size(p)-1,r={start,end,p,cidr:N.ip(start)+'/'+p};const matches=reservations.filter(a=>N.overlap(a,r)),used=matches.reduce((n,a)=>n+Math.min(a.end,end)-Math.max(a.start,start)+1,0),pct=used/N.size(p)*100,status=used===0?'free':used===N.size(p)?'reserved':'mixed';const whole=matches.find(a=>N.contains(a,r));const title=whole?whole.record.name:status==='mixed'?'Partly reserved':status==='free'?'Available':'Reserved';const b=button('',()=>{if(p===v.p&&p<32){tileDepth=Math.min(4,32-v.p);drawZoom()}else if(p===32&&v.p<32){zoomTo(r.cidr)}else if(p===32){const a=whole?.record;if(a){selected=a.id;page=Math.floor((start-N.parse(a.cidr).start)/256);renderInspector();$('inspector').scrollIntoView({behavior:'smooth',block:'start'})}notify(N.ip(start)+' · '+title)}else zoomTo(r.cidr)},'netblock '+status);b.style.setProperty('--fill',pct+'%');b.title=r.cidr+' · '+fmt(N.size(p))+' IP addresses · '+fmt(N.size(p)-used)+' unallocated';b.setAttribute('aria-label',b.title+'. '+(p===32?'Inspect address':'Zoom into block'));b.append(element('span',title,'block-label'),element('strong',r.cidr),element('span',fmt(N.size(p))+' IPs','block-count'),element('span',p===32?'•':'↗','block-arrow'));return b}));
